Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include<bits/stdc++.h>
using namespace std;

const int MAXV = 14043;
int y_arr[200000], cap_arr[200000], flow_arr[200000], cost_arr[200000];
vector<int> g[MAXV];
int edge_cnt = 0;

long long ans = 0;
long long dist[MAXV];
int par[MAXV], pe_arr[MAXV], inq[MAXV];
const long long INF = (long long)(1e18);
int S = MAXV - 2, T = MAXV - 1;

int residual(int idx) {
    return cap_arr[idx] - flow_arr[idx];
}

void push_flow() {
    fill(dist, dist + MAXV, INF);
    fill(par, par + MAXV, -1);
    fill(pe_arr, pe_arr + MAXV, -1);
    fill(inq, inq + MAXV, 0);
    dist[S] = 0;
    queue<int> q;
    q.push(S);
    inq[S] = 1;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        inq[u] = 0;
        for (int idx : g[u]) {
            if (!residual(idx)) continue;
            int c = cost_arr[idx];
            int v = y_arr[idx];
            if (dist[v] > dist[u] + c) {
                dist[v] = dist[u] + c;
                par[v] = u;
                pe_arr[v] = idx;
                if (!inq[v]) {
                    inq[v] = 1;
                    q.push(v);
                }
            }
        }
    }
    int cur = T;
    while (cur != S) {
        flow_arr[pe_arr[cur]]++;
        flow_arr[pe_arr[cur] ^ 1]--;
        cur = par[cur];
    }
    ans += dist[T];
}

void add_edge(int x, int y, int cap, int cost) {
    g[x].push_back(edge_cnt);
    y_arr[edge_cnt] = y;
    cap_arr[edge_cnt] = cap;
    flow_arr[edge_cnt] = 0;
    cost_arr[edge_cnt] = cost;
    edge_cnt++;
    g[y].push_back(edge_cnt);
    y_arr[edge_cnt] = x;
    cap_arr[edge_cnt] = 0;
    flow_arr[edge_cnt] = 0;
    cost_arr[edge_cnt] = -cost;
    edge_cnt++;
}

int main() {
    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;
    for (int i = 0; i < k; ++i) {
        int x;
        cin >> x;
        --x;
        add_edge(S, x, 1, 0);
    }
    int Tmax = 101;
    for (int i = 0; i < Tmax; ++i)
        add_edge(0 + i * n, T, k, i * c);
    for (int i = 0; i < m; ++i) {
        int x, y;
        cin >> x >> y;
        --x; --y;
        for (int t = 0; t < Tmax - 1; ++t)
            for (int j = 0; j < k; ++j)
                add_edge(x + t * n, y + t * n + n, 1, d * (j * 2 + 1));
        for (int t = 0; t < Tmax - 1; ++t)
            for (int j = 0; j < k; ++j)
                add_edge(y + t * n, x + t * n + n, 1, d * (j * 2 + 1));
    }
    for (int i = 0; i < n; ++i)
        for (int t = 0; t < Tmax - 1; ++t)
            add_edge(i + t * n, i + t * n + n, k, 0);
    for (int i = 0; i < k; ++i)
        push_flow();
    cout << ans << endl;
    return 0;
}
